                    | ClientTabIndexOrPaneId::ClientIdNoFocus(client_id) => {
                        match screen.get_active_tab_mut(client_id) {
                            Ok(tab) => tab
                                .replace_active_pane_with_editor_pane(pid, client_id)
                                .non_fatal(),
                            Err(err) => {
