                            log::error!(
                            "Could not find an active tab - is there at least 1 connected user?"
                        );
                        },
                    }
                },
                _ => {
                    let client_id = if screen.active_tab_ids.contains_key(&client_id) {
                        Some(client_id)
                    } else {
