                    },
                    ClientTabIndexOrPaneId::TabIndex(_tab_index)
                    | ClientTabIndexOrPaneId::TabIndexNoFocus(_tab_index) => {
                        log::error!("Cannot OpenInPlaceEditor with a TabIndex");
