                )?;
                // Set affected tab ID (tab_index is the ID here)
                completion_tx
                    .as_mut()
                    .map(|c| c.set_affected_tab_id(tab_index));
                let pane_group = screen.get_client_pane_group(&client_id);
                if !pane_group.is_empty() {
